&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;4+ years of&amp;nbsp;experience in&amp;nbsp;engineering,&amp;nbsp;manufacturing, product management,&amp;nbsp;operations,&amp;nbsp;FP&amp;amp;A, consulting, banking, or entrepreneurship&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
