&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Document&amp;nbsp;production&amp;nbsp;and&amp;nbsp;statistical process control&amp;nbsp;data&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
