&lt;div data-font-name=&quot;g_d0_f1&quot; data-angle=&quot;0&quot; data-canvas-width=&quot;140&quot;&gt;&lt;strong&gt;ADDITIONAL&amp;nbsp;REQUIREMENTS:&lt;/strong&gt;&lt;/div&gt;
