&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This is a hands-on position that will require standing for long durations of the day and directly interacting with other team members and hardware on the floor&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
