&lt;li&gt;&lt;span class=&quot;TextRun SCXW133033327 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW133033327 BCX0&quot;&gt;Create sourcing strategies for&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW133033327 BCX0&quot;&gt;assigned&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW133033327 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW133033327 BCX0&quot;&gt;connector suppliers, PCBA and Harnessing, whether it’s consigned or turnkey&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW133033327 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW55436350 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW55436350 BCX0&quot;&gt;Manage supplier base factories to ensure smooth transition from NPI rates to full production rates, including max capacity assessments, CAPEX NRE review and proposals, and manage supplier production line site changes to ensure qualification and upbring align with SpaceX production schedules&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW55436350 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
